    {
        if (is_null($default_product_id)) {
            array_push($this->openAPINullablesSetToNull, 'default_product_id');
        } else {
            $nullablesSetToNull = $this->getOpenAPINullablesSetToNull();
            $index = array_search('default_product_id', $nullablesSetToNull, true);
            if ($index !== false) {
                unset($nullablesSetToNull[$index]);
                $this->setOpenAPINullablesSetToNull($nullablesSetToNull);
            }
        }
        $this->container['default_product_id'] = $default_product_id;

        return $this;
